export interface UserPreferences {
  id: string;
  notificationsEnabled: boolean;
}

const preferences: Map<string, UserPreferences> = new Map([
  ["user_1", { id: "user_1", notificationsEnabled: false }],
]);

export async function getPreferences(
  userId: string,
): Promise<UserPreferences | null> {
  return preferences.get(userId) ?? null;
}

export async function toggleNotifications(
  userId: string,
): Promise<UserPreferences> {
  const current = preferences.get(userId);
  const updated: UserPreferences = {
    id: userId,
    notificationsEnabled: current ? !current.notificationsEnabled : true,
  };
  preferences.set(userId, updated);
  return updated;
}

