import { getPreferences } from "@/lib/data";
import { ToggleButton } from "./toggle-button";

const USER_ID = "user_1";

export default async function Home() {
  const prefs = await getPreferences(USER_ID);
  const enabled = prefs?.notificationsEnabled ?? false;

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently <strong>{enabled ? "ON" : "OFF"}</strong>
      </p>
      <ToggleButton userId={USER_ID} enabled={enabled} />
    </main>
  );
}

